import{z as s,x as d,o as i,c as p,q as t,j as l,D as e,d as n,s as r,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"生命周期假说","description":"","frontmatter":{"title":"生命周期假说","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/life-cycle-hypothesis.md","filePath":"econ/life-cycle-hypothesis.md","lastUpdated":1791413859000}'),C={name:"econ/life-cycle-hypothesis.md"};function A(c,a,m,h,u,f){const o=d("Mermaid");return i(),p("div",null,[a[2]||(a[2]=t('<h1 id="生命周期假说" tabindex="-1">生命周期假说 <a class="header-anchor" href="#生命周期假说" aria-label="Permalink to &quot;生命周期假说&quot;">​</a></h1><div class="epigraph"><p>储蓄不是收入的固定比例，而是把一生资源摊到工作期与退休期的计划；年龄、寿命和退休，比当期 $Y$ 更先进入问题。</p><footer>—— Modigliani and Brumberg, Utility Analysis and the Consumption Function, 1954；Ando and Modigliani, AER 1963</footer></div><p><a href="/econ/commitment-devices">上一课</a>处理自我之间的锁。本课回到<strong>时间一致</strong>的主干偏好，问另一缺口：有限寿命下，收入在工作期、消费要覆盖退休，储蓄率随年龄走。不重写指数贴现，不把承诺装置再推导一遍。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Keynes 的 \\(C=cY\\) 与 IS 会计把储蓄当成当期收入的残差。<a href="/econ/consumption-euler">欧拉</a>已经说可预测收入不应驱动 \\(\\Delta c\\)，但还没有年龄结构。Modigliani 与 Brumberg（1954）的生命周期假说（LCH）：人最大化一生效用，受一生劳动收入加初始资产的现值约束；典型路径是工作期储蓄、退休期负储蓄，财富在生命中段隆起。Ando 与 Modigliani（1963）把它写成可加总的消费函数：总消费依赖劳动收入与资产存量，边际消费倾向随人口年龄结构变。</p><p>缺口是把「跨期切点」从两期教室搬到有限寿命的日历上。遗赠暂时关掉，下一课才打开永久收入的无限期对照。</p><p><span class="marginnote">LCH 的资源是人力财富加非人力财富。利率改斜率也改现值，符号不定——与<a href="/econ/two-period-micro">两期</a>同一分解，不重写斯勒茨基矩阵。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>有限 \\(T\\)、确定寿命、完全借贷、指数 \\(\\beta\\)。内部解仍是欧拉沿年龄写下去；约束是一生现值。若 \\(r\\) 与时间偏好接近且 \\(u\\) 使消费平滑，则 \\(c\\) 大致平坦，储蓄 \\(=y_t-c\\) 随 \\(y_t\\) 的年龄剖面符号变化。加总时，增长经济里年轻人更多，总储蓄可以为正，即使每人退休时把财富吃完。</p><p><span class="marginnote">数字实例：工作 40 年、每年挣 50 万，退休 20 年零收入，一生资源 2000 万。完全平滑地摊到 60 年，每年消费约 33 万——工作期每年存约 17 万，退休期每年花 33 万，靠的就是中年攒下的资产。</span></p>',10)),(i(),l(B,null,{default:e(()=>[r(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20KEY%5B%22%E5%90%8C%E6%9C%9F%20C(Y)%22%5D%20--%3E%20LCH%5B%22%E4%B8%80%E7%94%9F%E7%8E%B0%E5%80%BC%E9%A2%84%E7%AE%97%22%5D%0A%20%20LCH%20--%3E%20AGE%5B%22%E5%B7%A5%E4%BD%9C%E5%82%A8%E8%93%84%2C%20%E9%80%80%E4%BC%91%E8%B4%9F%E5%82%A8%E8%93%84%22%5D%0A%20%20AGE%20--%3E%20AGG%5B%22%E6%80%BB%20C%20%E4%BE%9D%E8%B5%96%20Y%20%E4%B8%8E%E8%B5%84%E4%BA%A7%2C%20%E9%9A%8F%E5%B9%B4%E9%BE%84%E7%BB%93%E6%9E%84%E5%8F%98%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"本课确定环境。收入风险与缓冲存量后课再加。也不把住房、年金提前写成谜。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[n("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"机制是日历约束：劳动收入有起点和终点，偏好要的是跨期平滑。没有资本市场，人被锁在各年的 \\(y_t\\) 上，退休消费掉到零。有债券，人把高峰收入转移到低谷。这与承诺装置正交：LCH 用指数贴现，不需要锁自己；若再引入准双曲，金蛋可以解释「为何强制养老金被需求」，那是叠层，不是 LCH 原文。",-1)),(i(),l(B,null,{default:e(()=>[r(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20INC%5B%22%E6%94%B6%E5%85%A5%EF%BC%9A%E5%B7%A5%E4%BD%9C%E6%9C%9F%E9%AB%98%EF%BC%8C%E9%80%80%E4%BC%91%E5%90%8E%E4%B8%BA%E9%9B%B6%22%5D%20--%3E%20NO%5B%22%E6%97%A0%E5%80%9F%E8%B4%B7%E5%B8%82%E5%9C%BA%22%5D%0A%20%20INC%20--%3E%20YES%5B%22%E5%8F%AF%E5%80%9F%E5%8F%AF%E8%B4%B7%22%5D%0A%20%20NO%20--%3E%20N1%5B%22%E6%B6%88%E8%B4%B9%E8%B7%9F%E7%9D%80%E5%BD%93%E6%9C%9F%E6%94%B6%E5%85%A5%E8%B5%B0%EF%BC%8C%E9%80%80%E4%BC%91%E5%90%8E%E9%AA%A4%E9%99%8D%22%5D%0A%20%20YES%20--%3E%20Y1%5B%22%E6%B6%88%E8%B4%B9%E8%BF%91%E4%BC%BC%E5%B9%B3%E7%A8%B3%EF%BC%8C%E5%B7%A5%E4%BD%9C%E6%9C%9F%E5%AD%98%E3%80%81%E9%80%80%E4%BC%91%E6%9C%9F%E8%8A%B1%22%5D%0A%20%20Y1%20--%3E%20HUMP%5B%22%E8%B4%A2%E5%AF%8C%E5%91%88%E9%A9%BC%E5%B3%B0%EF%BC%8C%E9%80%80%E4%BC%91%E6%97%B6%E8%B6%8B%E5%90%91%E5%BD%92%E9%9B%B6%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p>宏观含义：战争、婴儿潮改变年龄结构，改变总储蓄与资产需求。本课只保留这条加总逻辑，不估计人口。</p><p><span class="marginnote">直觉类比（负储蓄）：退休期的「负储蓄」就是把当年攒下的资产一点点卖掉换生活费——先动债券、再动基金，像秋收后慢慢吃粮仓，而不是再种新粮。</span></p><p>与<a href="/econ/consumption-euler">欧拉</a>的接缝：年龄剖面是把同一条切点沿寿命写下去，再叠上劳动收入的日历形状。没有退休这一刀，LCH 就退回无限期平滑，与下一课 Friedman 更难分。本课故意把寿命有限、退休确定当作最小结构，收入风险与遗赠先关着。也不把年龄储蓄写成限价簿上的生命阶段订单——这里没有协议。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>经验上老年人仍持有大量财富，纯 LCH 的终点负储蓄过强——遗赠与长寿风险是后课。流动性约束使年轻人无法按永久资源借，年龄剖面变形。不确定收入让预防性储蓄抬高中年资产。这些是对 LCH 的补，不是把它退回 \\(C=cY\\)。</p><p><span class="marginnote">常见误区：以为人老了就会把存款花光。数据显示老年家庭常继续持有大量财富——遗赠动机、怕「人还在钱没了」的长寿恐惧、医疗支出不确定性，都在拖住负储蓄。纯 LCH 的「终点花光」在数据里偏强，边界一节说的就是这件事。</span></p><p>后课默认：说到生命周期，指有限寿命平滑；说到永久收入，指无限期或随机永久成分。两者近亲，下一课拆开 Friedman 的那一支。</p><p>有限寿命把退休写成确定的零劳动收入段；没有这一刀，模型退回无限期平滑。</p><p>加总储蓄随人口年龄结构变，这是 LCH 对 Keynes 同期消费函数的另一条拒绝。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LCH 把储蓄写成一生资源在工作与退休之间的配置，不是固定 \\(S=sY\\)。</li><li>财富随年龄隆起；加总消费依赖收入、资产和人口结构。</li><li>确定、完全市场、无遗赠是本课边界，后课逐项打开。</li><li>年龄隆起是日历约束，不是固定储蓄率。</li><li>遗赠与长寿风险是终点条件的后课缺口。</li><li>出处：Modigliani and Brumberg, 1954；Ando and Modigliani, <em>AER</em> 1963。</li></ul>',11))])}const F=s(C,[["render",A]]);export{D as __pageData,F as default};
